(function(){
  'use strict';
  const O=window.OperationsModel;
  const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const n=(x,d=0)=>Number.isFinite(x)?x.toLocaleString('en-US',{maximumFractionDigits:d}):'—';
  const badge=(status,labels={pass:'Cleared',fail:'Outside limits',pending:'Needs review'})=>`<span class="status ${status==='pass'?'success':status==='fail'?'danger':'neutral'}">${h(labels[status]||status)}</span>`;
  const date=x=>O.validDate(x)?new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(x+'T00:00:00Z')):'—';
  const input=(name,label,value,type='text',extra='')=>`<div class="field"><label for="op-${name}">${label}</label><input id="op-${name}" name="${name}" type="${type}" value="${h(value)}" ${extra}></div>`;
  const select=(name,label,value,options)=>`<div class="field"><label for="op-${name}">${label}</label><select id="op-${name}" name="${name}">${options.map(([v,l])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(l)}</option>`).join('')}</select></div>`;
  const types=[['H','Heavy'],['SH','Super-heavy'],['L','Light']];
  const statuses=[['pending','Not recorded'],['pass','Pass'],['fail','Fail']];
  const uid=()=>crypto.randomUUID();
  function create(api){
    const $=id=>document.getElementById(id), get=()=>api.getState().operations;
    let editingPassport=null,editingSupplier=null;
    const modal=document.createElement('dialog');modal.id='operations-dialog';modal.className='operations-dialog';document.body.append(modal);
    const err=message=>modal.querySelector('.field-error').textContent=message;
    const read=form=>Object.fromEntries(new FormData(form));
    const numeric=v=>v===undefined||v.trim()===''?null:Number(v);
    function open(title,body,onSubmit,onInput){
      modal.innerHTML=`<form id="operations-form"><div class="dialog-heading"><h2>${title}</h2><button type="button" class="icon-button op-close" aria-label="Close">×</button></div>${body}<p class="field-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button secondary op-close">Cancel</button><button class="button primary" type="submit">Save record</button></div></form>`;
      modal.querySelectorAll('.op-close').forEach(b=>b.onclick=()=>modal.close());
      const form=modal.querySelector('form');form.onsubmit=e=>{e.preventDefault();onSubmit(form);};if(onInput)form.oninput=()=>onInput(form);modal.showModal();
    }
    modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
    function readPassport(form){
      const data=read(form),p={...O.passport(),id:editingPassport||uid(),name:data.name.trim(),type:data.type,supplier:data.supplier.trim(),assayDate:data.assayDate,reference:data.reference.trim(),limitReference:data.limitReference.trim(),temperature:numeric(data.temperature),notes:data.notes.trim()};
      O.metrics.forEach(m=>{p.assay[m.key]=numeric(data['assay-'+m.key]);for(const side of ['contract','plant']){p[side][m.key]=numeric(data[side+'-'+m.key]);if(data[side+'-na-'+m.key])p[side+'NA'].push(m.key);}});
      return p;
    }
    function passportForm(id){
      editingPassport=id||null;const p=id?get().passports.find(p=>p.id===id):O.passport();
      open(id?'Edit cargo passport':'New cargo passport',`
        <p>Record a delivery assay and its agreed limits. All limits are inclusive maxima. Mark N/A only where the referenced contract or plant specification does not require a limit.</p>
        <div class="op-form-grid">${input('name','Cargo / delivery ID',p.name,'text','required maxlength="100"')}${select('type','Crude type',p.type,types)}${input('supplier','Supplier',p.supplier,'text','required maxlength="120"')}${input('assayDate','Assay date',p.assayDate,'date')}${input('reference','Assay report reference',p.reference,'text','maxlength="180"')}${input('limitReference','Contract / plant limits reference',p.limitReference,'text','maxlength="180"')}${input('temperature','Viscosity test temperature (°C)',p.temperature,'number','step="any" min="-273.14"')}</div>
        <div class="table-scroll"><table class="op-assay-table"><thead><tr><th>Property</th><th>Measured assay</th><th>Contract max</th><th>Plant max</th><th>Check</th></tr></thead><tbody>${O.metrics.map(m=>`<tr><th scope="row">${m.label}<small>${m.unit}</small></th><td><input aria-label="${m.label} measured assay" name="assay-${m.key}" type="number" min="0" ${['bsw','asphaltenes'].includes(m.key)?'max="100"':''} step="any" value="${h(p.assay[m.key])}"></td>${['contract','plant'].map(side=>`<td><input aria-label="${m.label} ${side} maximum" name="${side}-${m.key}" type="number" min="0" step="any" value="${h(p[side][m.key])}" ${p[side+'NA'].includes(m.key)?'disabled':''}><label class="op-checkbox"><input name="${side}-na-${m.key}" type="checkbox" ${p[side+'NA'].includes(m.key)?'checked':''}> N/A</label></td>`).join('')}<td data-check="${m.key}"></td></tr>`).join('')}</tbody></table></div>
        <div class="field notes-field"><label for="op-notes">Notes / specification exceptions</label><textarea id="op-notes" name="notes" rows="2" maxlength="1000">${h(p.notes)}</textarea></div><div class="op-preview" id="passport-preview"></div>`,form=>{
          const next=readPassport(form);const ops=get();const index=ops.passports.findIndex(p=>p.id===next.id);if(index<0)ops.passports.push(next);else ops.passports[index]=next;O.resetTests(ops);api.changed('Cargo passport saved.');modal.close();
        },form=>preview(form));
      function preview(form){for(const m of O.metrics)for(const side of ['contract','plant']){form.elements[side+'-'+m.key].disabled=form.elements[side+'-na-'+m.key].checked;}
        const r=O.passportReview(readPassport(form));r.rows.forEach(row=>modal.querySelector(`[data-check="${row.key}"]`).innerHTML=badge(row.status,{pass:'Within limits',fail:'Above / invalid',pending:'Incomplete'}));
        $('passport-preview').innerHTML=badge(r.status)+`<span>${r.metadata?'Report and specification references recorded.':'Add assay date, report, limits reference, and viscosity temperature to complete the passport.'}</span>`;
      }preview(modal.querySelector('form'));
    }
    function supplierForm(id){
      editingSupplier=id||null;const s=id?get().suppliers.find(s=>s.id===id):O.supplier();
      open(id?'Edit supplier / delivery':'New supplier / delivery',`
        <p>One record per planned delivery or replacement nomination. Quality is derived from the linked passport for the same supplier and crude type.</p><div class="op-form-grid">
        ${input('name','Supplier',s.name,'text','required maxlength="120"')}${select('type','Crude type',s.type,types)}${select('role','Nomination',s.role,[['primary','Primary delivery'],['backup','Backup / replacement']])}
        ${select('passportId','Cargo passport',s.passportId,[['','Select a passport'],...get().passports.map(p=>[p.id,`${p.name} · ${p.type} · ${p.supplier}`])])}
        ${input('volume','Nominated volume (bbl)',s.volume,'number','min="0" step="any"')}${input('arrival','Confirmed arrival date',s.arrival,'date')}</div>
        <div class="op-checks"><label class="op-checkbox"><input type="checkbox" name="volumeConfirmed" ${s.volumeConfirmed?'checked':''}> Volume confirmed with supplier</label><label class="op-checkbox"><input type="checkbox" name="slotConfirmed" ${s.slotConfirmed?'checked':''}> Delivery slot / arrival confirmed</label></div>
        <div class="field notes-field"><label for="op-notes">Confirmation reference / follow-up</label><textarea id="op-notes" name="notes" rows="3" maxlength="1000">${h(s.notes)}</textarea></div><div id="supplier-preview" class="op-preview"></div>`,form=>{
          const next=readSupplier(form),ops=get();const index=ops.suppliers.findIndex(s=>s.id===next.id);if(index<0)ops.suppliers.push(next);else ops.suppliers[index]=next;O.resetApproval(ops);api.changed('Supplier / delivery record saved.');modal.close();
        },form=>preview(form));
      function readSupplier(form){const d=read(form);return {...O.supplier(),id:editingSupplier||uid(),name:d.name.trim(),type:d.type,role:d.role,passportId:d.passportId,volume:numeric(d.volume),volumeConfirmed:!!d.volumeConfirmed,arrival:d.arrival,slotConfirmed:!!d.slotConfirmed,notes:d.notes.trim()};}
      function preview(form){const r=O.supplierReview(readSupplier(form),get());$('supplier-preview').innerHTML=`${badge(r.status,{pass:'Ready for nomination',fail:'Quality gap',pending:'Confirmation needed'})}<span>Quality: ${r.quality==='pass'?'cleared':r.quality==='fail'?'outside limits':'not cleared'} · Volume: ${r.volume?'confirmed':'pending'} · Arrival: ${r.arrival?'confirmed':'pending'}</span>`;}preview(modal.querySelector('form'));
    }
    function render(state,result){
      const ops=state.operations,r=O.release(ops,state,result),pass=ops.passports.filter(p=>O.passportReview(p).status==='pass').length;
      $('cargo-workspace').innerHTML=`<section class="card op-register"><div class="card-heading"><div><h2>Cargo register</h2><p>${ops.passports.length} passports · ${pass} quality cleared</p></div><button class="button primary" id="add-passport">New passport</button></div>
      <div class="table-scroll"><table class="op-table"><thead><tr><th>Cargo / report</th><th>Crude / supplier</th><th>Assay date</th><th>Quality check</th><th>Actions</th></tr></thead><tbody>${ops.passports.map(p=>`<tr><td><strong>${h(p.name)}</strong><small>${h(p.reference||'No report reference')}</small></td><td>${h(p.type)}<small>${h(p.supplier)}</small></td><td>${date(p.assayDate)}</td><td>${badge(O.passportReview(p).status)}</td><td><button class="text-button" data-edit-passport="${h(p.id)}">Review / edit</button><button class="text-button" data-use-passport="${h(p.id)}" ${Number.isFinite(p.assay.salt)&&Number.isFinite(p.assay.bsw)?'':'disabled'}>Use in blend ↗</button><button class="text-button op-remove" data-remove-passport="${h(p.id)}" aria-label="Remove ${h(p.name)}">Remove</button></td></tr>`).join('')}</tbody></table></div>${ops.passports.length?'':'<div class="op-empty">No cargo passports yet. Add the assay and agreed limits for each delivery.</div>'}<p class="op-foot">Quality status uses the recorded assay, contract limits, and plant limits. Using a passport copies its salt, BS&W, and supplier into the blend.</p></section>
      <section class="card"><div class="card-heading"><div><h2>Selected blend cargo</h2><p>Passports linked to the active H / SH / L inputs.</p></div></div><div class="op-selected">${state.cargo.map((c,i)=>{const p=ops.passports.find(p=>p.id===ops.selectedPassports[i]);return `<div><span class="micro-label">${h(c.type)} · ${n(state.ratios[i],1)}%</span><strong>${h(p?.name||'No passport linked')}</strong><span>${badge(r.selected[i].status,{pass:state.ratios[i]===0?'Not required':'Quality cleared',fail:'Outside limits',pending:'Needs passport'})}</span></div>`;}).join('')}</div></section>`;
      $('add-passport').onclick=()=>passportForm();
      $('cargo-workspace').onclick=e=>{const edit=e.target.closest('[data-edit-passport]'),use=e.target.closest('[data-use-passport]'),remove=e.target.closest('[data-remove-passport]');if(edit)passportForm(edit.dataset.editPassport);if(use)api.usePassport(ops.passports.find(p=>p.id===use.dataset.usePassport));if(remove){const id=remove.dataset.removePassport;ops.passports=ops.passports.filter(p=>p.id!==id);ops.selectedPassports=ops.selectedPassports.map(v=>v===id?null:v);O.resetTests(ops);api.changed('Passport removed from this scenario.');}};
      renderSupply(ops,r);
      renderClearance(ops,r);
      $('release-overview').innerHTML=`<div><span class="micro-label">Plant release</span><strong>${r.status==='cleared'?'Cleared':r.status==='blocked'?'Gap remains':'Evidence pending'}</strong><span>${r.gates.filter(g=>g.status==='pass').length} of ${r.gates.length} checks complete</span></div><button class="text-button" id="open-clearance">Review clearance →</button>`;
      $('open-clearance').onclick=()=>api.switchTab('clearance');
    }
    function renderSupply(ops,r){
      const plan=r.plan;
      $('supplier-workspace').innerHTML=`<section class="card op-register"><div class="card-heading"><div><h2>Suppliers & deliveries</h2><p>Qualify primary deliveries and backup nominations against a cargo passport.</p></div><button class="button primary" id="add-supplier">New delivery</button></div>
      <div class="table-scroll"><table class="op-table"><thead><tr><th>Supplier / crude</th><th>Nomination</th><th>Quality</th><th>Volume</th><th>Arrival / slot</th><th>Readiness</th><th>Actions</th></tr></thead><tbody>${ops.suppliers.map(s=>{const q=O.supplierReview(s,ops);return `<tr><td><strong>${h(s.name)}</strong><small>${h(s.type)}</small></td><td>${s.role==='backup'?'Backup':'Primary'}</td><td>${badge(q.quality)}</td><td>${n(s.volume)} bbl<small>${q.volume?'Confirmed':'Not confirmed'}</small></td><td>${date(s.arrival)}<small>${q.arrival?'Slot confirmed':'Slot pending'}</small></td><td>${badge(q.status,{pass:'Ready',fail:'Quality gap',pending:'Pending'})}</td><td><button class="text-button" data-edit-supplier="${h(s.id)}">Edit</button><button class="text-button op-remove" data-remove-supplier="${h(s.id)}" aria-label="Remove delivery from ${h(s.name)}">Remove</button></td></tr>`;}).join('')}</tbody></table></div>${ops.suppliers.length?'':'<div class="op-empty">No deliveries recorded. Add primary supply or a qualified replacement.</div>'}
      <div class="op-planning"><div class="field"><label for="planning-start">Planning start date</label><input id="planning-start" type="date" value="${h(ops.planningStart)}"></div><div class="field"><label for="planning-days">Planning horizon (days)</label><input id="planning-days" type="number" min="1" max="365" step="1" value="${h(ops.planningDays)}"></div><p>${plan.valid?`${date(ops.planningStart)} – ${date(plan.end)}`:'Set a planning date to compare deliveries with demand.'}</p></div>
      <div class="table-scroll"><table class="op-table op-demand"><thead><tr><th>Crude</th><th>Blend requirement</th><th>Confirmed primary supply</th><th>Uncovered volume</th></tr></thead><tbody>${plan.rows.map(row=>`<tr><th scope="row">${row.type}</th><td>${n(row.required)} bbl</td><td>${plan.valid?n(row.confirmed):'—'} bbl</td><td>${n(row.shortfall)} bbl</td></tr>`).join('')}</tbody></table></div><p class="op-foot">Only quality-cleared primary deliveries linked to the selected blend passports, with confirmed volumes and arrival slots within the inclusive planning window, count toward supply. Backup records stay separate until promoted to primary.</p></section>`;
      $('add-supplier').onclick=()=>supplierForm();
      $('supplier-workspace').onclick=e=>{const edit=e.target.closest('[data-edit-supplier]'),remove=e.target.closest('[data-remove-supplier]');if(edit)supplierForm(edit.dataset.editSupplier);if(remove){ops.suppliers=ops.suppliers.filter(s=>s.id!==remove.dataset.removeSupplier);O.resetApproval(ops);api.changed('Delivery removed from this scenario.');}};
      $('planning-start').onchange=e=>{ops.planningStart=e.target.value;O.resetApproval(ops);api.changed();};
      $('planning-days').onchange=e=>{const days=Number(e.target.value);if(!Number.isInteger(days)||days<1||days>365){e.target.value=ops.planningDays;api.toast('Planning horizon must be a whole number from 1 to 365.');return;}ops.planningDays=days;O.resetApproval(ops);api.changed();};
    }
    function renderClearance(ops,r){
      const c=ops.clearance;
      $('clearance-workspace').innerHTML=`<div class="op-clearance-grid"><section class="card op-release"><div class="card-heading"><div><h2>Release check</h2><p>Active blend, selected cargo, and confirmed supply.</p></div>${badge(r.status==='cleared'?'pass':r.status==='blocked'?'fail':'pending',{pass:'Cleared',fail:'Gap remains',pending:'Evidence pending'})}</div><ul class="op-gates">${r.gates.map(g=>`<li><span>${g.label}</span>${badge(g.status,{pass:'Complete',fail:'Gap remains',pending:'Pending'})}</li>`).join('')}</ul><p class="op-foot">${r.status==='cleared'?'All required checks and the recorded plant approval are complete.':r.status==='blocked'?'Adjust the blend, cargo, or test results and re-test before recording approval.':'Complete the missing evidence and supply confirmations before recording approval.'}</p></section>
      <form id="plant-limits-form" class="card"><div class="card-heading"><div><h2>Plant limits</h2><p>Limits from the supplied release rules and your unit specification.</p></div></div><div class="op-limit-values"><span>Outlet salt <b>&lt;2 PTB</b></span><span>Outlet BS&W <b>&lt;0.05%</b></span></div><div class="op-form-grid two">${input('internalTarget','Internal salt target (PTB)',c.internalTarget,'number','min="0.001" max="1.999" step="any"')}${input('tanLimit','Unit TAN maximum (mg KOH/g)',c.tanLimit,'number','min="0" step="any"')}${input('metalLimit','Unit Ni + V maximum (ppm)',c.metalLimit,'number','min="0" step="any"')}</div><p class="op-foot">${r.internalMet?'Fresh and aged samples meet the internal salt target.':'Internal salt target is advisory; confirm both measured results.'} Hard release limits remain strict.</p><div class="op-action-bar"><button class="button secondary" type="submit">Apply limits</button></div></form></div>
      <form id="sample-evidence-form" class="card"><div class="card-heading"><div><h2>Fresh & aged sample evidence</h2><p>Record both tests for the selected blend. Blend, cargo, or process edits clear these records.</p></div></div><div class="op-samples">${['fresh','aged'].map(key=>{const s=c[key];return `<div class="op-sample"><div class="op-sample-heading"><h3>${key==='fresh'?'Fresh sample':'Aged sample'}</h3>${badge(r[key].status,{pass:'Tests pass',fail:'Test gap',pending:'Incomplete'})}</div><div class="op-form-grid two">${select(key+'-compatibility','Compatibility',s.compatibility,statuses)}${input(key+'-salt','Measured outlet salt (PTB)',s.salt,'number','min="0" step="any"')}${input(key+'-bsw','Measured outlet BS&W (%)',s.bsw,'number','min="0" max="100" step="any"')}${input(key+'-tan','Measured TAN (mg KOH/g)',s.tan,'number','min="0" step="any"')}${input(key+'-metal','Measured Ni + V (ppm)',s.metal,'number','min="0" step="any"')}${input(key+'-date','Test date',s.date,'date')}${input(key+'-reference','Test report reference',s.reference,'text','maxlength="180"')}</div></div>`;}).join('')}</div><div class="op-action-bar"><button class="button primary" type="submit">Apply test records</button></div></form>
      <form id="plant-approval-form" class="card"><div class="card-heading"><div><h2>Recorded plant approval</h2><p>Enter the plant's approval reference after reviewing the evidence.</p></div></div><div class="op-form-grid">${select('approval','Approval decision',c.approval,[['pending','Not recorded'],['pass','Approved by plant'],['fail','Rejected / re-test']])}${input('approvedBy','Approver',c.approvedBy,'text','maxlength="120"')}${input('approvedAt','Approval date',c.approvedAt,'date')}${input('approvalRef','Approval reference',c.approvalRef,'text','maxlength="180"')}</div><div class="field notes-field"><label for="op-clearance-notes">Plant comments / follow-up</label><textarea id="op-clearance-notes" rows="2" maxlength="1000">${h(c.notes)}</textarea></div><p class="op-foot">Evidence and approvals are manually recorded and saved with the scenario in this browser.</p><div class="op-action-bar"><button class="button primary" type="submit">Apply approval record</button></div></form>`;
      $('plant-limits-form').onsubmit=e=>{
        e.preventDefault();const d=read(e.target),values=Object.fromEntries(['internalTarget','tanLimit','metalLimit'].map(k=>[k,numeric(d[k])]));
        if(values.internalTarget===null||values.internalTarget<=0||values.internalTarget>=2){api.toast('Internal salt target must be above 0 and below 2 PTB.');return;}
        Object.assign(c,values);O.resetApproval(ops);api.changed('Plant limits applied. Approval must be reviewed again.');
      };
      $('sample-evidence-form').onsubmit=e=>{
        e.preventDefault();const d=read(e.target);for(const kind of ['fresh','aged'])for(const key of ['compatibility','salt','bsw','tan','metal','date','reference'])c[kind][key]=['salt','bsw','tan','metal'].includes(key)?numeric(d[kind+'-'+key]):d[kind+'-'+key].trim();
        O.resetApproval(ops);api.changed('Fresh and aged test records applied.');
      };
      $('plant-approval-form').onsubmit=e=>{
        e.preventDefault();const d=read(e.target);for(const key of ['approval','approvedBy','approvedAt','approvalRef'])c[key]=d[key].trim();c.notes=$('op-clearance-notes').value;api.changed('Plant approval record applied.');
      };
    }
    return {render};
  }
  window.OperationsUI={create};
})();
